"""Graph representations, adapters, algorithms, and serialization.

All source paths below were read in full. Bounds distinguish live counts from
slot high-water marks and account for the selected graph representation.
"""


def section(title, *paragraphs, table=None, bullets=None):
    value = {"title": title, "paragraphs": list(paragraphs)}
    if table is not None:
        value["table"] = table
    if bullets is not None:
        value["bullets"] = bullets
    return value


def table(columns, rows):
    return {"columns": columns, "rows": rows}


def datatype(name, header, summary, *sections, covers=None):
    value = {"name": name, "header": header, "summary": summary,
             "sections": list(sections)}
    if covers:
        value["covers"] = covers
    return value


